 // 0 resets the accumulator so only 4 is summed"] # [doc = " assert_eq!(lookup[&1], 5 + 9);"] # [doc = " assert_eq!(lookup.get(&2), None); // 10 resets the accumulator and nothing is summed afterward"] # [doc = " assert_eq!(lookup[&3], 7);"] # [doc = " assert_eq!(lookup.len(), 3);      // The final keys are only 0, 1 and 2"] # [doc = " ```"] pub fn aggregate < FO , R > (self , mut operation : FO) -> HashMap < K , R > where FO : FnMut (Option < R > , & K , V) -> Option < R > , { let mut destination_map = HashMap :: new () ; self . iter . for_each (| (key , val) | { let acc = destination_map . remove (& key) ; if let Some (op_res) = operation (acc , & key , val) { destination_map . insert (key , op_res) ; } }) ; destination_map } # [doc = " Groups elements from the `GroupingMap` source by key and applies `operation` to the elements"] # [doc = " of each group sequentially, passing the previously accumulated value, a reference to the key"] # [doc = " and the current element as arguments, and stores the results in a new map."] # [doc = ""] # [doc = " `init` is called to obtain the initial value of each accumulator."] # [doc = ""] # [doc = " `operation` is a function that is invoked on each element with the following parameters:"] # [doc = "  - the current value of the accumulator of the group;"] # [doc = "  - a reference to the key of the group this element belongs to;"] # [doc = "  - the element from the source being accumulated."] # [doc = ""] # [doc = " Return a `HashMap` associating the key of each group with the result of folding that group's elements."] # [doc = ""] # [doc = " ```"] # [doc = " use itertools::Itertools;"] # [doc = ""] # [doc = " #[derive(Debug, Default)]"] # [doc = " struct Accumulator {"] # [doc = "     acc: usize,"] # [doc = " }"] # [doc = ""] # [doc = " let lookup = (1..=7)"] # [doc = "     .into_grouping_map_by(|&n| n % 3)"] # [doc = "     .fold_with(|_key, _val| Default::default(), |Accumulator { acc }, _key, val| {"] # [doc = "         let ac